// FillWithKEVuln :
func FillWithKEVuln(r *models.ScanResult, cnf config.KEVulnConf, logOpts logging.LogOpts) error {
	client, err := newGoKEVulnDBClient(&cnf, logOpts)
	if err != nil {
		return err
	}
	defer func() {
		if err := client.closeDB(); err != nil {
			logging.Log.Errorf("Failed to close DB. err: %+v", err)
		}
	}()

	nKEV := 0
	if client.driver == nil {
		var cveIDs []string
		for cveID := range r.ScannedCves {
			cveIDs = append(cveIDs, cveID)
		}
		prefix, err := util.URLPathJoin(client.baseURL, "cves")
		if err != nil {
			return err
		}
		responses, err := getKEVulnsViaHTTP(cveIDs, prefix)
		if err != nil {
			return err
		}
		for _, res := range responses {
			var kevulns kevulndb.Response
			if err := json.Unmarshal([]byte(res.json), &kevulns); err != nil {
				return err
			}
			v, ok := r.ScannedCves[res.request.cveID]
			if !ok {
				continue
			}
			v.KEVs = buildKEVs(kevulns)
			if len(v.KEVs) > 0 {
				nKEV++
			}
			r.ScannedCves[res.request.cveID] = v
		}
	} else {
		for cveID, vuln := range r.ScannedCves {
			if cveID == "" {
				continue
			}
			kevulns, err := client.driver.GetKEVByCveID(cveID)
			if err != nil {
				return err
			}
			vuln.KEVs = buildKEVs(kevulns)
			if len(vuln.KEVs) > 0 {
				nKEV++
			}
			r.ScannedCves[cveID] = vuln
		}
	}

	logging.Log.Infof("%s: Known Exploited Vulnerabilities are detected for %d CVEs", r.FormatServerName(), nKEV)
	return nil
}

func buildKEVs(source kevulndb.Response) []models.KEV {
	var kevs []models.KEV
	for _, cisa := range source.CISA {
		var dueDate *time.Time
		if cisa.DueDate.Year() > 1000 {
			dueDate = &cisa.DueDate
		}
		kevs = append(kevs, models.KEV{
			Type:                       models.CISAKEVType,
			VendorProject:              cisa.VendorProject,
			Product:                    cisa.Product,
			VulnerabilityName:          cisa.VulnerabilityName,
			ShortDescription:           cisa.ShortDescription,
			RequiredAction:             cisa.RequiredAction,
			KnownRansomwareCampaignUse: cisa.KnownRansomwareCampaignUse,
			DateAdded:                  cisa.DateAdded,
			DueDate:                    dueDate,
			CISA:                       &models.CISAKEV{Note: cisa.Notes},
		})
	}
	for _, vulncheck := range source.VulnCheck {
		var dueDate *time.Time
		if vulncheck.DueDate != nil && vulncheck.DueDate.Year() > 1000 {
			dueDate = vulncheck.DueDate
		}
		details := &models.VulnCheckKEV{}
		for _, xdb := range vulncheck.VulnCheckXDB {
			details.XDB = append(details.XDB, models.VulnCheckXDB{
				XDBID: xdb.XDBID, XDBURL: xdb.XDBURL,
				DateAdded: xdb.DateAdded, ExploitType: xdb.ExploitType,
				CloneSSHURL: xdb.CloneSSHURL,
			})
		}
		for _, exploitation := range vulncheck.VulnCheckReportedExploitation {
			details.ReportedExploitation = append(details.ReportedExploitation, models.VulnCheckReportedExploitation{
				URL: exploitation.URL, DateAdded: exploitation.DateAdded,
			})
		}
		kevs = append(kevs, models.KEV{
			Type:                       models.VulnCheckKEVType,
			VendorProject:              vulncheck.VendorProject,
			Product:                    vulncheck.Product,
			VulnerabilityName:          vulncheck.Name,
			ShortDescription:           vulncheck.Description,
			RequiredAction:             vulncheck.RequiredAction,
			KnownRansomwareCampaignUse: vulncheck.KnownRansomwareCampaignUse,
			DateAdded:                  vulncheck.DateAdded,
			DueDate:                    dueDate,
			VulnCheck:                  details,
		})
	}
	return kevs
}

